                mix_original_bgm=mix_bgm,
                bgm_volume=bgm_vol,
            )
            duration_info = (
                f"Original: {result['original_duration']:.1f}s | "
                f"Final: {result['final_duration']:.1f}s | "
                f"Extended by: {result['total_extension']:.1f}s"
            )
        else:
            result = editor.stitch(session)
